import __manifest__

with open(__manifest__.__file__) as f:
    manifest = eval(f.read())


def test_data_key_exists():
    assert 'data' in manifest


def test_data_is_list():
    assert isinstance(manifest['data'], list)


def test_original_view_file_present():
    assert 'views/issue_analysis_views.xml' in manifest['data']


def test_ai_config_views_file_present():
    assert 'views/ai_config_views.xml' in manifest['data']


def test_data_has_at_least_two_entries():
    assert len(manifest['data']) >= 2
